BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(trim(name)) BETWEEN 2 AND 160),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),display_name text NOT NULL CHECK(length(trim(display_name)) BETWEEN 1 AND 160),email text,phone text,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','suspended','deactivated')),locale text NOT NULL DEFAULT 'en-IN',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(email IS NOT NULL OR phone IS NOT NULL));
CREATE UNIQUE INDEX users_tenant_email_uq ON users(tenant_id,lower(email)) WHERE email IS NOT NULL;
CREATE UNIQUE INDEX users_tenant_phone_uq ON users(tenant_id,phone) WHERE phone IS NOT NULL;
CREATE TABLE roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),code text NOT NULL,name text NOT NULL,UNIQUE(tenant_id,code));
CREATE TABLE user_roles(user_id uuid NOT NULL REFERENCES users(id),role_id uuid NOT NULL REFERENCES roles(id),granted_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,role_id));
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),sku text NOT NULL,name text NOT NULL,description text,category text NOT NULL,base_unit text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,sku));
CREATE TABLE grocery_cycles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),code text NOT NULL,starts_on date NOT NULL,delivery_from date NOT NULL,delivery_to date NOT NULL,cutoff_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','OPEN','CLOSED','FULFILLING','COMPLETED','CANCELLED')),UNIQUE(tenant_id,code),CHECK(delivery_to>=delivery_from));
CREATE TABLE baskets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),customer_id uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','PAUSED','CLOSED')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,customer_id));
CREATE TABLE basket_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),basket_id uuid NOT NULL REFERENCES baskets(id),version integer NOT NULL CHECK(version>0),effective_cycle_id uuid NOT NULL REFERENCES grocery_cycles(id),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(basket_id,version));
CREATE TABLE basket_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),basket_version_id uuid NOT NULL REFERENCES basket_versions(id) ON DELETE CASCADE,product_id uuid NOT NULL REFERENCES products(id),quantity numeric(12,3) NOT NULL CHECK(quantity>0),unit_code text NOT NULL,substitution_policy text NOT NULL CHECK(substitution_policy IN ('NO_SUBSTITUTION','ASK_CUSTOMER','PREAPPROVED_ONLY')),UNIQUE(basket_version_id,product_id));
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),customer_id uuid NOT NULL REFERENCES users(id),cycle_id uuid NOT NULL REFERENCES grocery_cycles(id),order_type text NOT NULL CHECK(order_type IN ('RECURRING','ONE_TIME','AD_HOC')),fulfilment_status text NOT NULL DEFAULT 'PLACED',payment_status text NOT NULL DEFAULT 'PENDING',currency char(3) NOT NULL DEFAULT 'INR',subtotal_minor bigint NOT NULL CHECK(subtotal_minor>=0),discount_minor bigint NOT NULL DEFAULT 0 CHECK(discount_minor>=0),tax_minor bigint NOT NULL DEFAULT 0 CHECK(tax_minor>=0),total_minor bigint NOT NULL CHECK(total_minor>=0),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX orders_tenant_cycle_idx ON orders(tenant_id,cycle_id,created_at DESC);
CREATE TABLE order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),product_id uuid NOT NULL REFERENCES products(id),quantity numeric(12,3) NOT NULL CHECK(quantity>0),unit_price_minor bigint NOT NULL CHECK(unit_price_minor>=0),line_total_minor bigint NOT NULL CHECK(line_total_minor>=0),source_type text NOT NULL CHECK(source_type IN ('RECURRING','ONE_TIME','AD_HOC')));
CREATE TABLE farmer_listings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),farmer_id uuid NOT NULL REFERENCES users(id),product_id uuid NOT NULL REFERENCES products(id),available_quantity numeric(12,3) NOT NULL CHECK(available_quantity>0),unit_code text NOT NULL,price_minor bigint CHECK(price_minor>=0),status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','SUBMITTED','UNDER_REVIEW','CHANGES_REQUESTED','APPROVED','REJECTED','SUSPENDED','EXPIRED','WITHDRAWN')),reviewed_by uuid REFERENCES users(id),reviewed_at timestamptz,review_note text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(status<>'APPROVED' OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)));
CREATE INDEX farmer_listings_public_idx ON farmer_listings(tenant_id,product_id) WHERE status='APPROVED';
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),actor_id uuid NOT NULL REFERENCES users(id),action text NOT NULL,resource text NOT NULL,resource_id text,outcome text NOT NULL CHECK(outcome IN ('success','failure','denied')),metadata jsonb NOT NULL DEFAULT '{}'::jsonb,correlation_id text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_events_tenant_time_idx ON audit_events(tenant_id,occurred_at DESC);
CREATE TABLE idempotency_keys(tenant_id uuid NOT NULL REFERENCES tenants(id),actor_id uuid NOT NULL REFERENCES users(id),key text NOT NULL CHECK(length(key) BETWEEN 8 AND 128),request_hash text NOT NULL,response_status integer,response_body jsonb,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,actor_id,key));
COMMIT;
